use arena_scores::Board;
use std::sync::Arc;

fn main() {
    // Deadlock check: opposite-direction transfers.
    let b = Arc::new(Board::new());
    b.join(1, 100);
    b.join(2, 100);
    let threads: Vec<_> = (0..8)
        .map(|i| {
            let b = b.clone();
            std::thread::spawn(move || {
                for _ in 0..10_000 {
                    if i % 2 == 0 {
                        b.transfer(1, 2, 1);
                        b.award(1, 1);
                    } else {
                        b.transfer(2, 1, 1);
                        b.award(2, 1);
                    }
                }
            })
        })
        .collect();
    for t in threads {
        t.join().unwrap();
    }
    let s1 = b.score(1);
    let s2 = b.score(2);
    let total = b.total();
    println!("score1={s1} score2={s2} total={total}");
    assert_eq!(s1, 40_100);
    assert_eq!(s2, 40_100);
    assert_eq!(total, 80_200);
    println!("STRESS OK");
}
